        var wr2 = [a > 0 ? iv(x0, Infinity, true, false) : iv(-Infinity, x0, false, true), a > 0 ? iv(-Infinity, x0, false, false) : iv(x0, Infinity, false, false), a > 0 ? iv(fneg(x0), Infinity, false, false) : iv(-Infinity, fneg(x0), false, false), iv(-Infinity, Infinity, false, false), a > 0 ? iv(x0, Infinity, true, false) : iv(x0, Infinity, true, false)];
