        if (kind === 'ln') { var a = ri(2, 5), b = ri(1, 6) * pick([1, -1]); var cor = '\\dfrac{' + a + '}{' + poly([a, b]) + '}'; return { q: 'Đạo hàm của hàm số $y=\\ln(' + poly([a, b]) + ')$ là', correct: M(cor), wrongs: ['\\dfrac{1}{' + poly([a, b]) + '}', '\\dfrac{' + b + '}{' + poly([a, b]) + '}', '\\dfrac{' + a + '}{' + poly([a, b]) + '}\\ln ' + a, '\\ln ' + a + '\\cdot' + poly([a, b]), '\\dfrac{' + poly([a, b]) + '}{' + a + '}'].map(M), exp: '$(\\ln u)\'=\\dfrac{u\'}{u}$ nên $y\'=\\dfrac{' + a + '}{' + poly([a, b]) + '}$.', level: 'TH' }; }
        if (kind === 'e') { var a1 = ri(1, 3), b1 = pick([-3, -2, -1, 1, 2, 3, 4]); var ex = a1 + 'x^2' + (b1 >= 0 ? '+' : '') + b1 + 'x'; ex = poly([a1, b1, 0]); var cor1 = '(' + poly([2 * a1, b1]) + ')e^{' + ex + '}'; return { q: 'Đạo hàm của hàm số $y=e^{' + ex + '}$ là', correct: M(cor1), wrongs: ['e^{' + ex + '}', '(' + poly([a1, b1]) + ')e^{' + ex + '}', '(' + poly([2 * a1, b1]) + ')e^{' + poly([2 * a1, b1]) + '}', '(' + ex + ')e^{' + ex + '-1}', '(' + poly([2 * a1, b1 + 1]) + ')e^{' + ex + '}'].map(M), exp: '$(e^u)\'=u\'e^u$ nên $y\'=(' + poly([2 * a1, b1]) + ')e^{' + ex + '}$.', level: 'TH' }; }
        var b2 = pick([2, 3, 5]), s = ri(1, 4), cor2 = b2 + '^{x}\\ln ' + b2;
