        return { q: 'Đạo hàm của hàm số $y=' + fx + '$ là', correct: M(cc), wrongs: [b2 + '^{' + (s === 1 ? 'x' : s + 'x') + '}', (s === 1 ? '' : s + '\\cdot') + 'x\\cdot' + b2 + '^{' + (s === 1 ? 'x' : s + 'x') + '-1}', b2 + '^{' + (s === 1 ? 'x' : s + 'x') + '}\\ln ' + b2 + (s === 1 ? '+1' : ''), '\\dfrac{' + b2 + '^{' + (s === 1 ? 'x' : s + 'x') + '}}{\\ln ' + b2 + '}', s === 1 ? '\\dfrac{' + b2 + '^{x}}{\\ln ' + b2 + '}' : s + '\\cdot' + b2 + '^{' + s + 'x}'].map(M), exp: '$(a^u)\'=u\'a^u\\ln a$ nên $y\'=' + cc + '$.', level: 'TH' };
