            need(b1 !== 0 && b2 !== 0 && a2 !== 0 && (a2 * b1) % b2 === 0); var mp = F(a2 * b1, b2); /* a=(m;a2) cùng phương b=(b1;b2): m/b1=a2/b2 */ mp = F(a2 * b1, b2);
