            if (kind === 'r') { var r = ri(1, 6); r2 = r * r; q = 'Phương trình đường tròn có tâm $I(' + a + ';' + b + ')$ và bán kính $R=' + r + '$ là'; ex = '$(x-a)^2+(y-b)^2=R^2$ với $a=' + a + '$, $b=' + b + '$, $R^2=' + r2 + '$.'; }
            else if (kind === 'pt') { var dx = ri(-4, 4), dy = ri(-4, 4); need(dx || dy); r2 = dx * dx + dy * dy; q = 'Phương trình đường tròn có tâm $I(' + a + ';' + b + ')$ và đi qua điểm $A(' + (a + dx) + ';' + (b + dy) + ')$ là'; ex = 'Bán kính $R^2=IA^2=' + dx * dx + '+' + dy * dy + '=' + r2 + '$. Phương trình: ' + M(circ(a, b, r2)) + '.'; }
            else { var ex1 = ri(-4, 4), ey1 = ri(-4, 4); var x1 = a + ex1, y1 = b + ey1, x2 = a - ex1, y2 = b - ey1; need(ex1 || ey1); r2 = ex1 * ex1 + ey1 * ey1; q = 'Phương trình đường tròn đường kính $AB$ với $A(' + x1 + ';' + y1 + ')$, $B(' + x2 + ';' + y2 + ')$ là'; ex = 'Tâm là trung điểm $AB$: $I(' + a + ';' + b + ')$. Bán kính $R^2=IA^2=' + r2 + '$. Phương trình: ' + M(circ(a, b, r2)) + '.'; }
