            var m, a, b, c; if (Math.random() < 0.35) { var t = pick([[3, 4, 5], [5, 12, 13], [8, 15, 17], [6, 8, 10]]), k = ri(1, 3); a = t[0] * k; b = t[1] * k; c = t[2] * k; } else { a = ri(3, 15); b = ri(3, 15); c = ri(3, 15); } var s = [a, b, c].sort(function (x, y) { return x - y; }); need(s[0] + s[1] > s[2] && !(s[0] === s[1] && s[1] === s[2])); var l = s[0] * s[0] + s[1] * s[1], r = s[2] * s[2]; var kind = l > r ? 'nhọn' : l === r ? 'vuông' : 'tù';
