            if (kind === 'mid') { need(A.every(function (z, i) { return (z + B[i]) % 2 === 0; })); var M = A.map(function (z, i) { return (z + B[i]) / 2; }); var Bp = A.map(function (z, i) { return 2 * M[i] - z; }); return mcT('Trong không gian $Oxyz$, cho $A' + vS(A) + '$ và $B' + vS(B) + '$. Trung điểm $M$ của đoạn $AB$ có tọa độ là', vS(M), [vS(A.map(function (z, i) { return B[i] - z; })), vS(M.map(function (z) { return z + 1; })), vS(A.map(function (z, i) { return z + B[i]; })), vS(M.map(function (z) { return -z; }))], '$M=\\left(\\dfrac{x_A+x_B}{2};\\dfrac{y_A+y_B}{2};\\dfrac{z_A+z_B}{2}\\right)=' + vS(M) + '$.', 'TH'); }
