        function gdata() { var w = pick([2, 5, 10]), s0 = pick([0, 5, 10, 20]), k = ri(4, 5), fr = []; for (var i = 0; i < k; i++) fr.push(ri(2, 12)); var N = fr.reduce(function (a, b) { return a + b; }, 0); return { w: w, s0: s0, k: k, fr: fr, N: N, mid: fr.map(function (_, i) { return s0 + w * i + w / 2; }) }; }
        function gtab(d) { var h = '\\begin{array}{|c|' + d.fr.map(function () { return 'c|'; }).join('') + '}\\hline \\text{Nhóm}&' + d.fr.map(function (_, i) { return '[' + (d.s0 + d.w * i) + ';' + (d.s0 + d.w * (i + 1)) + ')'; }).join('&') + '\\\\\\hline \\text{Tần số}&' + d.fr.join('&') + '\\\\\\hline\\end{array}'; return '$' + h + '$'; }
