            var acc = 0, idx = 0; for (var i = 0; i < d.k; i++) { acc += d.fr[i]; if (acc >= d.N / 2) { idx = i; break; } } var L = function (i) { return '[' + (d.s0 + d.w * i) + ';' + (d.s0 + d.w * (i + 1)) + ')'; };
