        function mcT(q, cor, wr, ex, lv, fig) { var seen = {}; seen[cor] = 1; var w = []; wr.forEach(function (x) { if (!seen[x]) { seen[x] = 1; w.push(x); } }); need(w.length >= 3); var o = { q: q, correct: cor, wrongs: w, exp: ex, level: lv || 'TH' }; if (fig) o.fig = fig; return o; }
