        function quadV() { var q = pick(QUAD), v = shuf([q[0], q[1], q[2]]).map(function (x) { return Math.random() < 0.5 ? x : -x; }); return { v: v, n: q[3] }; }
        // ---- Xác suất
        add('l12_xs_pab_cong_thuc', 12, XS, 'Tính $P(A|B)$ từ $P(AB)$ và $P(B)$ (công thức xác suất có điều kiện)', 'NB', function () {
            var r = pick([0.2, 0.25, 0.4, 0.5, 0.6, 0.75]), pb = pick([0.2, 0.4, 0.5, 0.8]), pab = Math.round(r * pb * 1000) / 1000;
            return dmc('Cho hai biến cố $A,B$ với $P(B)=' + dv(pb) + '$ và $P(AB)=' + dv(pab) + '$. Xác suất $P(A|B)$ bằng', r, [pab * pb, 1 - r, pab + pb, Math.min(1, pb / pab), r / 2, Math.min(1, pab / (1 - pb))], '$P(A|B)=\\dfrac{P(AB)}{P(B)}=\\dfrac{' + dv(pab) + '}{' + dv(pb) + '}=' + dv(r) + '$.', 'NB');
        });
