            var s = ri(7, 10), kinds = [['có ít nhất một con xuất hiện mặt $6$ chấm', function (a, b) { return a === 6 || b === 6; }], ['hai con xuất hiện số chấm giống nhau', function (a, b) { return a === b; }], ['tổng số chấm là số chẵn', function (a, b) { return (a + b) % 2 === 0; }]], k = pick(kinds), n = 0, m = 0;
            for (var a = 1; a <= 6; a++) for (var b = 1; b <= 6; b++) if (a + b >= s) { n++; if (k[1](a, b)) m++; } need(m > 0);
            return fnum(F(m, n), 'Có $' + n + '$ kết quả có tổng $\\ge' + s + '$, trong đó có $' + m + '$ kết quả ' + k[0].replace('$', '$') + '. Xác suất cần tìm là $\\dfrac{' + m + '}{' + n + '}$.', 'Gieo đồng thời hai con xúc xắc cân đối. Biết tổng số chấm xuất hiện trên hai con xúc xắc không nhỏ hơn $' + s + '$, xác suất để ' + k[0] + ' bằng', [F(m, 36), F(n, 36), F(m, n + 1)], 'TH');
