                function (ok) { var v = r(pab / pb); return { t: '$P(A|B)=' + dv(ok ? v : r(v + 0.1)) + '$.', why: '$P(A|B)=\\dfrac{' + dv(pab) + '}{' + dv(pb) + '}=' + dv(v) + '$.' }; },
                function (ok) { var v = r(pab / pa); return { t: '$P(B|A)=' + dv(ok ? v : r(pab / pb)) + '$.', why: '$P(B|A)=\\dfrac{' + dv(pab) + '}{' + dv(pa) + '}=' + dv(v) + '$.' }; },
