                function (ok) { return { t: 'Xác suất sản phẩm do máy B sản xuất là $' + dv((ok ? o.sh[1] : o.sh[1] + 10) / 100) + '$.', why: 'Máy B sản xuất $' + o.sh[1] + '\\%$.' }; },
                function (ok) { return { t: 'Nếu sản phẩm do máy C sản xuất thì xác suất bị lỗi là $' + dv((ok ? o.d[2] : o.d[2] + 1) / 100) + '$.', why: 'Tỉ lệ lỗi của máy C là $' + o.d[2] + '\\%$.' }; },
