                function (ok) { var T = t0 - 1, V = W0 + a * T * T / 2 + b * T; return { t: 'Sau $' + T + '$ phút, lượng nước trong bể là $' + iv(ok, V) + '$ lít.', why: '$V(' + T + ')=' + W0 + '+\\int_0^{' + T + '}f(t)dt=' + V + '$.' }; },
