                function (ok) { var Q = P0.map(function (x, i) { return x + t0 * v[i]; }); return { t: 'Sau $' + t0 + '$ phút, drone ở vị trí $' + ptw(Q, ok, 2) + '$.', why: '$A+' + t0 + '\\vec v=' + vc(Q) + '$.' }; },
