                function (ok) { return { t: 'Góc giữa hai đường thẳng $AB\'$ và $AD\'$ bằng $' + angS(ok ? 60 : 45) + '$.', why: '$\\overrightarrow{AB\'}=(' + k + ';0;' + k + ')$, $\\overrightarrow{AD\'}=(0;' + k + ';' + k + ')$, $\\cos=\\dfrac{' + k * k + '}{' + 2 * k * k + '}=\\dfrac12$ nên góc $60^\\circ$.' }; },
                function (ok) { return { t: 'Gọi $\\varphi$ là góc giữa đường thẳng $AC\'$ và mặt phẳng $(ABCD)$. Khi đó $\\cos\\varphi=' + (ok ? '\\dfrac{\\sqrt6}{3}' : '\\dfrac{\\sqrt3}{3}') + '$.', why: '$\\sin\\varphi=\\dfrac{k}{k\\sqrt3}=\\dfrac{\\sqrt3}{3}$ nên $\\cos\\varphi=\\sqrt{1-\\tfrac13}=\\dfrac{\\sqrt6}{3}$.' }; }
