        var INF = Infinity, G1 = 'Giải tích 12 › Ứng dụng đạo hàm (Chương I)', OX = 'Hình học 12 › Tọa độ trong không gian', VT = 'Hình học 12 › Vectơ trong không gian', NH = 'Giải tích 12 › Nguyên hàm, tích phân', XS = 'Thống kê và xác suất 12 › Xác suất có điều kiện';
        function dot3(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }


        // ===== v176: lớp 12 – thống kê ghép nhóm (hai mẫu, tần số thiếu), tích phân từng khúc, góc hình lập phương, hộp tọa độ
        function gd(k) { var w = pick([2, 5, 10]), s0 = pick([0, 5, 10, 20]), fr = []; for (var i = 0; i < k; i++) fr.push(ri(2, 12)); return { w: w, s0: s0, k: k, fr: fr }; }
        function gN(d) { return d.fr.reduce(function (a, b) { return a + b; }, 0); }
