                function (ok) { return { t: 'Khoảng biến thiên của hai mẫu ' + (ok ? 'bằng nhau' : 'khác nhau') + '.', why: 'Hai mẫu có cùng các nhóm nên $R=' + A.w * 4 + '$ cho cả hai.' + (ok ? '' : ' Do đó mệnh đề "khác nhau" sai.') }; },
