                function (ok) { var better = (vA < vB) === ok; return { t: 'Điểm số của lớp ' + (better ? 'A' : 'B') + ' đồng đều hơn lớp ' + (better ? 'B' : 'A') + ' (xét theo độ lệch chuẩn).', why: '$s_A^2=' + dec(vA) + '$, $s_B^2=' + dec(vB) + '$; phương sai nhỏ hơn thì đồng đều hơn.' }; }
