                function (ok) { var P = ok ? [a, b, c] : [a, b, -c]; return { t: 'Vectơ $\\overrightarrow{AC\'}$ có tọa độ $(' + P.join(';') + ')$.', why: '$A$ là gốc nên $\\overrightarrow{AC\'}=(' + [a, b, c].join(';') + ')$.' }; },
                function (ok) { var P = ok ? [F(a, 2), F(b, 2), F(c, 2)] : [F(a, 2), F(b, 2), F(c)]; return { t: 'Tâm $I$ của hình hộp có tọa độ $(' + P.map(tex).join(';') + ')$.', why: '$I$ là trung điểm $AC\'$ nên $I\\left(' + [F(a, 2), F(b, 2), F(c, 2)].map(tex).join(';') + '\\right)$.' }; },
                function (ok) { return { t: 'Độ dài đường chéo $AC\'$ bằng $' + (ok ? L : L + 1) + '$.', why: '$AC\'=\\sqrt{' + a + '^{2}+' + b + '^{2}+' + c + '^{2}}=' + L + '$.' }; }
