            var pos = sols.filter(function (z) { return z > 1e-9; }).sort(function (a, b) { return a - b; })[0]; var den = p[3] * k, f = F(Math.round(pos * den), den); need(Math.abs(f.n / f.d - pos) < 1e-9);
