            var cF = F(sg * c, h), sF = F(s, h), tF = F(sg * s, sg * c), k = pick(['sin', 'tan', 'cot']), v = k === 'sin' ? sF : k === 'tan' ? F(s, sg * c) : F(sg * c, s);
