            var P0 = pts[0], Pk = pts[k], cor = T(V2(P0 + Pk)), wr = uniq(cor, [T(V2(Pk + P0)), T(V2(P0 + pts[k - 1])), T('\\vec0'), T(V2(pts[1] + Pk)), T(V2(P0 + pts[1]))]);
