        var QUAD = [[1, 2, 2, 3], [2, 3, 6, 7], [2, 6, 9, 11], [4, 4, 7, 9], [1, 4, 8, 9], [6, 6, 7, 11], [2, 10, 11, 15], [3, 4, 12, 13]];
        function quadV() { var q = pick(QUAD), v = shuf([q[0], q[1], q[2]]).map(function (x) { return Math.random() < 0.5 ? x : -x; }); return { v: v, n: q[3] }; }
        function ptS(P) { return '(' + P.join(';') + ')'; }
