        function IV(a, b) { var f = function (x) { return x === -INF ? '-\\infty' : x === INF ? '+\\infty' : String(x); }; return '(' + f(a) + ';' + f(b) + ')'; }
        function cubBBT(sgn, p, q, yp, yq) { var up = sgn > 0, cols = [{ x: '-∞', mark: '', l: { v: up ? '-∞' : '+∞', lv: up ? 0 : 2 } }, { x: p, mark: '0', l: { v: yp, lv: up ? 2 : 0 } }, { x: q, mark: '0', l: { v: yq, lv: up ? 0 : 2 } }, { x: '+∞', mark: '', l: { v: up ? '+∞' : '-∞', lv: up ? 2 : 0 } }]; return { t: 'bbt', cols: cols, signs: up ? ['+', '-', '+'] : ['-', '+', '-'] }; }
        function cubParam() { var sgn = pick([1, -1]), p = ri(-3, 1), q = p + ri(2, 3), hi = ri(1, 7), lo = hi - ri(2, 6), yMax = hi, yMin = lo; return { sgn: sgn, p: p, q: q, yp: sgn > 0 ? yMax : yMin, yq: sgn > 0 ? yMin : yMax, xmax: sgn > 0 ? p : q, xmin: sgn > 0 ? q : p, ymax: yMax, ymin: yMin }; }
        function cubGraph(extra) { var sgn = pick([1, -1]), p = ri(-3, 1), q = p + pick([2, 2, 4]), sm = (p + q) / 2, d = ri(-3, 3), cf = [sgn, -3 * sm * sgn, 3 * p * q * sgn, d], yp = ev(cf, p), yq = ev(cf, q); return { sgn: sgn, p: p, q: q, cf: cf, yp: yp, yq: yq, xmax: sgn > 0 ? p : q, xmin: sgn > 0 ? q : p, ymax: Math.max(yp, yq), ymin: Math.min(yp, yq) }; }
        function cubFig(o) { var vals = [o.yp, o.yq]; var fig = { t: 'plot', num: o.cf, den: null, xr: [o.p - 2, o.q + 2], yr: [Math.min(o.ymin - 2, -1), Math.max(o.ymax + 2, 1)], lbx: [o.p, o.q].filter(function (v) { return v !== 0; }), lby: vals.filter(function (v, i, a) { return v !== 0 && a.indexOf(v) === i; }), marks: [[o.p, o.yp], [o.q, o.yq]], dots: [[o.p, o.yp], [o.q, o.yq]] }; return fig; }
        function fpGraph(c, r1, r2, extra) { var vals = []; for (var x = r1 - 1.5; x <= r2 + 1.5; x += 0.1) vals.push(ev(c, x)); var yr = [Math.floor(Math.min.apply(null, vals.concat([-1]))) - 1, Math.ceil(Math.max.apply(null, vals.concat([1]))) + 1]; yr = [Math.max(yr[0], -8), Math.min(yr[1], 8)]; var fig = { t: 'plot', num: c, den: null, xr: [r1 - 2, r2 + 2], yr: yr, lbx: [], lby: [], marks: [], dots: [] }; for (var i = r1 - 1; i <= r2 + 1; i++) fig.lbx.push(i); for (var j = Math.max(yr[0] + 1, -6); j <= Math.min(yr[1] - 1, 6); j++) if (Math.abs(j) % 2 === 0 && j !== 0) fig.lby.push(j); return Object.assign(fig, extra || {}); }
