        // ---- Bài 15
        add('l10_sa_hs_giadien', 10, GH, 'Trả lời ngắn: tính tiền điện theo giá bậc thang (hàm số cho bởi nhiều công thức)', 'TH', function () {
            var p1 = pick([2, 3]), p2 = p1 + 1, p3 = p2 + pick([1, 2]), x = ri(110, 190), v = 50 * p1 + 50 * p2 + (x - 100) * p3;
            return fl(v, 'Tiền điện: $50\\cdot' + p1 + '+50\\cdot' + p2 + '+(' + x + '-100)\\cdot' + p3 + '=' + v + '$ (nghìn đồng).', 'Giá điện sinh hoạt tính theo bậc thang: $50$ kWh đầu giá $' + p1 + '$ nghìn đồng/kWh; từ kWh thứ $51$ đến $100$ giá $' + p2 + '$ nghìn đồng/kWh; từ kWh thứ $101$ trở đi giá $' + p3 + '$ nghìn đồng/kWh. Một hộ dùng $' + x + '$ kWh trong tháng phải trả bao nhiêu nghìn đồng?', [v - p3, v + p3, 100 * p1 + 50 * p2 + (x - 150) * p3], 'TH');
        });
