            var a = pick([-2, -1, 1, 2]), b = ri(-4, 4), c = ri(-3, 3), f = function (x) { return a * x * x + b * x + c; }, xs = pick([[-1, 1, 2], [0, 1, 2], [-1, 0, 2], [-2, 0, 1]]), x3 = pick([3, -3, 4]), v = f(x3);
            return fl(v, 'Gọi $y=ax^2+bx+c$. Thế ba điểm được $a=' + a + '$, $b=' + b + '$, $c=' + c + '$. Khi đó $y(' + x3 + ')=' + v + '$.', 'Parabol $(P):y=ax^2+bx+c$ đi qua ba điểm $(' + xs[0] + ';' + f(xs[0]) + ')$, $(' + xs[1] + ';' + f(xs[1]) + ')$, $(' + xs[2] + ';' + f(xs[2]) + ')$. Giá trị của $y$ tại $x=' + x3 + '$ bằng', [v + 1, v - 1, -v || 5, a + b + c], 'VD');
