                function (ok) { var up = a - b > 0; return { t: 'Dãy số $(u_n)$ là dãy ' + (ok === up ? 'tăng' : 'giảm') + '.', why: '$u_{n+1}-u_n=\\dfrac{' + (a - b) + '}{(n+1)(n+2)}$ nên dãy ' + (up ? 'tăng' : 'giảm') + '.' }; },
