            var exs = { 'SAB|ABCD': 'Mặt phẳng $(SAB)$ chứa $SA\\perp(ABCD)$ nên $(SAB)\\perp(ABCD)$.', 'SAD|ABCD': 'Mặt phẳng $(SAD)$ chứa $SA\\perp(ABCD)$ nên $(SAD)\\perp(ABCD)$.', 'SAC|ABCD': 'Mặt phẳng $(SAC)$ chứa $SA\\perp(ABCD)$ nên $(SAC)\\perp(ABCD)$.', 'SAB|SAD': '$AB\\perp AD$ và $AB\\perp SA$ nên $AB\\perp(SAD)$, mà $AB\\subset(SAB)$ nên $(SAB)\\perp(SAD)$.', 'SAC|SBD': '$BD\\perp AC$, $BD\\perp SA$ nên $BD\\perp(SAC)$, mà $BD\\subset(SBD)$ nên $(SBD)\\perp(SAC)$.' };
            return mcT('Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình vuông, $SA\\perp(ABCD)$. Mệnh đề nào sau đây đúng?', st(t), shuf(fs).slice(0, 3).map(st), exs[t[0] + '|' + t[1]], 'TH');
