        function IV(a, ac, b, bc) { return { a: a, ac: ac, b: b, bc: bc }; }
        function ivEmpty(i) { return i.a > i.b || (i.a === i.b && !(i.ac && i.bc)); }
        function norm(arr) {
            arr = arr.filter(function (i) { return !ivEmpty(i); }).sort(function (u, v) { return u.a - v.a || (u.ac ? 0 : 1) - (v.ac ? 0 : 1); }); var out = [];
            arr.forEach(function (i) { var l = out[out.length - 1]; if (l && (i.a < l.b || (i.a === l.b && (i.ac || l.bc)))) { if (i.b > l.b || (i.b === l.b && i.bc)) { l.b = i.b; l.bc = i.bc; } } else out.push(IV(i.a, i.ac, i.b, i.bc)); }); return out;
        }
        function inter(A, B) { var r = []; A.forEach(function (u) { B.forEach(function (v) { var a, ac, b, bc; if (u.a > v.a) { a = u.a; ac = u.ac; } else if (u.a < v.a) { a = v.a; ac = v.ac; } else { a = u.a; ac = u.ac && v.ac; } if (u.b < v.b) { b = u.b; bc = u.bc; } else if (u.b > v.b) { b = v.b; bc = v.bc; } else { b = u.b; bc = u.bc && v.bc; } r.push(IV(a, ac, b, bc)); }); }); return norm(r); }
        function uni(A, B) { return norm(A.concat(B)); }
        function comp(A) { var r = [], cur = -Infinity, cc = false; A = norm(A); A.forEach(function (i) { r.push(IV(cur, cc, i.a, !i.ac)); cur = i.b; cc = !i.bc; }); r.push(IV(cur, cc, Infinity, false)); return norm(r); }
