            if (useTan) ex = 'Vì $\\tan\\alpha$ xác định nên $\\cos\\alpha\\ne0$. Chia cả tử và mẫu của $P$ cho $\\cos\\alpha$: $P=\\dfrac{' + lin(a, b, '\\tan\\alpha', '') + '}{' + lin(c, d, '\\tan\\alpha', '') + '}$. Thay $\\tan\\alpha=' + frac(p, q) + '$ được $P=' + (Math.abs(den) === 1 ? '' : '\\dfrac{' + num + '}{' + den + '}=') + dd(v, 2) + '$.';
            else ex = 'Vì $\\cot\\alpha$ xác định nên $\\sin\\alpha\\ne0$. Chia cả tử và mẫu của $P$ cho $\\sin\\alpha$: $P=\\dfrac{' + lin(a, b, '', '\\cot\\alpha') + '}{' + lin(c, d, '', '\\cot\\alpha') + '}$. Thay $\\cot\\alpha=' + p + '$ được $P=' + (Math.abs(den) === 1 ? '' : '\\dfrac{' + num + '}{' + den + '}=') + dd(v, 2) + '$.';
            var q2 = 'Cho góc $\\alpha$ thỏa mãn $' + given + '$. Tính giá trị của biểu thức $P=' + P + '$ (viết dưới dạng số thập phân).';
