            var m = pick([60, 80, 100, 120, 150, 200]), g = pick([30, 40, 45, 50, 60]), a = pick([50, 55, 60, 65, 70, 75]); var b = 180 - a - g; need(b > 10); var AB = m * sn(g) / sn(b); need(AB < 1000 && Math.round(AB) >= 10);
